    /**
     * Populates the given array with values generated by the provided factory function.
     * The factory function is called with the index of each array element to generate the corresponding value.
     *
     * @param <T>    the type of the array elements
     * @param array  the array to be populated; must not be null
     * @param factory a function to generate elements, using the index of the array as input; must not be null
     * @return the populated array
     * @throws NullPointerException if the array or factory parameter is null
     */
    public static <T> T[] generateContents(T[] array, IntFunction<? extends T> factory) {
        Objects.requireNonNull(factory, "Factory parameter must not be null!");
        Objects.requireNonNull(array, "Array parameter must not be null!");
        
        for (int index = 0; index < array.length; index++) array[index] = factory.apply(index);
        return array;
    }
    
    /**
     * Generates a new array of the specified type and length, and populates it
     * using the provided factory function. Each element in the array is created 
     * by invoking the factory function with its corresponding index.
     *
     * @param <T>      the type of the array elements
     * @param clazz    the class type of the array elements; must not be null
     * @param length   the length of the array to generate; must be non-negative
     * @param factory  a function to generate elements based on their index; must not be null
     * @return a newly created and populated array
     * @throws IllegalArgumentException if the specified length is negative
     * @throws NullPointerException if the clazz or factory parameter is null
     */
    @SuppressWarnings("unchecked")
    public static <T> T[] generate(Class<T> clazz, int length, IntFunction<? extends T> factory) {
        Preconditions.checkArgument(length >= 0, "Length must be non-negative!");
        
        T[] array = (T[]) Array.newInstance(clazz, length);
        return generateContents(array, factory);
    }
    
    /**
     * Populates the given array with values generated by the provided factory function.
     * The factory function is called with the index of each array element to generate the corresponding value.
     *
     * @param array   the array to be populated; must not be null
     * @param factory a function to generate elements, using the index of the array as input; must not be null
     * @return the populated integer array
     * @throws NullPointerException if the array or factory parameter is null
     */
