    // Uses Fisher-Yates algorithm
    public static <T> void shuffle(T[] array, RandomSource rand) {
        for (int i = array.length - 1; i > 0; i--) {
            int index = rand.nextInt(i + 1);
            T element = array[i];
            
            array[i] = array[index];
            array[index] = element;
        }
    }

